#!/usr/bin/env python3
"""Verify committed generated files carry an AUTO-GENERATED banner.

Every source file the build or toolchain emits and we keep under version
control must self-mark in its first lines so nobody hand-edits it. The
authoritative mark for diff-hiding is `.gitattributes` (linguist-generated);
this check covers the human-facing half: the DO-NOT-EDIT banner.

Formats that cannot carry a comment are exempt by design:
  - assets/game/**/manifests/*.json (pure JSON output;
    the content_hash inside is the integrity signal)
  - extraction YAMLs without the `reloc_` prefix are hand-authored ROM
    recipes — they are inputs, not generator output.
"""

import re
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[3]

GLOBS = [
    "generated/include/*/reloc_data*.h",
    "generated/src/*/RelocFileTable.??.*",  # .<region>.{h,cpp}
    "generated/src/*/ssb64_reloc_rebuild*.cpp",
    "assets/game/**/reloc_*.yml",
]

BANNER = re.compile(r"auto-?generated|generated by|do not edit", re.IGNORECASE)
SCAN_LINES = 15


def main() -> int:
    failures = []
    checked = 0
    for pattern in GLOBS:
        for path in sorted(ROOT.glob(pattern)):
            text = path.read_text(encoding="utf-8", errors="replace").splitlines()
            checked += 1
            if not any(BANNER.search(line) for line in text[:SCAN_LINES]):
                failures.append(path.relative_to(ROOT))

    if failures:
        print("check_generated_headers: generated files missing an "
              "AUTO-GENERATED banner in the first "
              f"{SCAN_LINES} lines:")
        for f in failures:
            print(f"  {f}")
        print("Regenerate via the owning tool in tools/code-generation/ — "
              "do not hand-edit.")
        return 1
    print(f"check_generated_headers: clean ({checked} generated file(s))")
    return 0


if __name__ == "__main__":
    sys.exit(main())
